package com.aistock.prediction.comparison;
import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;
import java.net.URI;import java.net.http.*;import java.time.Duration;import java.nio.ByteBuffer;import java.io.ByteArrayOutputStream;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;
import org.springframework.http.HttpStatus;
final class BoundedComparisonHttp {
 private final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();private final String token;private final ObjectMapper mapper;
 BoundedComparisonHttp(String token,ObjectMapper mapper){this.token=token;this.mapper=mapper;}
 JsonNode call(String base,String path,Object body,int seconds){if(token.isBlank()||base==null||base.isBlank())throw error("COMPARISON_MARKET_UNAVAILABLE");try{var builder=HttpRequest.newBuilder(URI.create(base).resolve(path)).timeout(Duration.ofSeconds(seconds)).header("X-Service-Token",token).header("Accept","application/json");com.aistock.prediction.marketuse.MarketUseContext.headers().forEach(builder::header);if(body==null)builder.GET();else builder.header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body)));var subscriber=new Limited();var future=client.sendAsync(builder.build(),i->subscriber);try{var response=future.get(seconds,TimeUnit.SECONDS);if(response.statusCode()>=300&&response.statusCode()<400)throw error("COMPARISON_MARKET_UNAVAILABLE");var n=mapper.readTree(response.body());if(n==null||!n.isObject())throw error("COMPARISON_MARKET_UNAVAILABLE");if(response.statusCode()!=200){String code=n.path("code").asText();throw error(Set.of("MARKET_USE_BINDING_MISMATCH","MARKET_USE_ALREADY_RELEASED","MARKET_VERSION_USE_BLOCKED","MARKET_USE_NOT_READY","MARKET_USE_UNAVAILABLE","MARKET_VERSION_UNAVAILABLE","RESOURCE_NOT_FOUND").contains(code)?code:"COMPARISON_MARKET_UNAVAILABLE");}return n;}finally{future.cancel(true);subscriber.cancel();}}catch(BusinessException e){throw e;}catch(InterruptedException e){Thread.currentThread().interrupt();throw error("COMPARISON_MARKET_UNAVAILABLE");}catch(Exception e){throw error("COMPARISON_MARKET_UNAVAILABLE");}}
 static BusinessException error(String c){return new BusinessException(c,"股票比较依赖暂不可用",HttpStatus.SERVICE_UNAVAILABLE);}
 private static final class Limited implements HttpResponse.BodySubscriber<byte[]> {
  private final ByteArrayOutputStream bytes=new ByteArrayOutputStream();private final CompletableFuture<byte[]> body=new CompletableFuture<>();private final AtomicReference<Flow.Subscription> subscription=new AtomicReference<>();
  public CompletionStage<byte[]> getBody(){return body;}public void onSubscribe(Flow.Subscription s){if(!subscription.compareAndSet(null,s)||body.isDone()){s.cancel();return;}s.request(1);}public void onNext(List<ByteBuffer> buffers){if(body.isDone())return;for(var b:buffers){if(b.remaining()>524288-bytes.size()){cancel();return;}var chunk=new byte[b.remaining()];b.get(chunk);bytes.writeBytes(chunk);}var s=subscription.get();if(s!=null&&!body.isDone())s.request(1);}public void onError(Throwable t){body.completeExceptionally(t);}public void onComplete(){body.complete(bytes.toByteArray());}void cancel(){var s=subscription.get();if(s!=null)s.cancel();body.completeExceptionally(new java.io.IOException("Comparison evidence body cancelled"));}
 }
}
